export default function config({ scheduledAt }) {
  const spreadsheetId = "YOUR_SPREADSHEET_ID",
    sheetName = "Sheet1",
    subject = "YOUR_SUBJECT";
  const templates = [
    { day: 0, body: "Hello {name},<br><br>Would you like to talk about {company}?" },
    { day: 3, body: "Hello {name},<br><br>Following up on my earlier message." },
    { day: 8, body: "Hello {name},<br><br>One last follow-up." },
  ];
  const quoted = "'" + sheetName.replace(/'/g, "''") + "'";
  return { spreadsheetId, sheetName, range: quoted, subject, templates, now: scheduledAt };
}

