export default function plan({ values, now }) {
  const header = ["email", "name", "company", "first_emailed", "thread_id", "sequence", "pending"];
  if (!Array.isArray(values) || header.some((h, i) => values[0]?.[i] !== h))
    throw Error("Expected headers email,name,company,first_emailed,thread_id,sequence,pending");
  const weekday = new Date(now).getUTCDay();
  if (weekday === 0 || weekday === 6) return { contacts: [] };
  const contacts = [],
    seen = new Set();
  for (let i = 1; i < values.length; i++) {
    const [email = "", name = "", company = "", first = "", thread = "", seq = "", pending = ""] =
      values[i];
    const placeholders = Object.fromEntries(values[0].map((h, j) => [h, values[i][j] ?? ""]));
    if (!email) continue;
    if (seen.has(email.toLowerCase())) throw Error("Duplicate recipient email");
    seen.add(email.toLowerCase());
    if (pending) continue;
    if (!first && !thread && !seq)
      contacts.push({ email, name, company, first, thread, seq: 0, row: i + 1, placeholders });
    else if (first && thread && /^[1-9][0-9]*$/.test(String(seq)))
      contacts.push({
        email,
        name,
        company,
        first,
        thread,
        seq: Number(seq),
        row: i + 1,
        placeholders,
      });
    else throw Error("Incomplete campaign state for " + email);
  }
  return { contacts };
}

