export default function next({ contacts, previous, templates, subject, now, sheetName }) {
  const index = previous?.index ?? 0,
    c = contacts[index],
    more = !!c,
    t = more ? templates[c.seq] : null;
  let due = false,
    body = "";
  if (t) {
    const days = c.first ? (Date.parse(now) - Date.parse(c.first)) / 86400000 : 0;
    due = Number.isFinite(days) && days >= t.day;
    if (due)
      body = t.body.replace(/\{([a-zA-Z0-9_-]+)\}/g, (_, k) => {
        if (!(k in c.placeholders)) throw Error("Missing placeholder column " + k);
        return String(c.placeholders[k] ?? "")
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;");
      });
  }
  const prefix = "'" + sheetName.replace(/'/g, "''") + "'!";
  return {
    state: { index: index + 1 },
    more,
    current: c ?? {},
    due,
    follow: !!c?.thread,
    threadId: c?.thread ?? "",
    to: c?.email ?? "",
    subject,
    body,
    pendingRange: prefix + "G" + (c?.row ?? 2),
    finalRange: prefix + "D" + (c?.row ?? 2) + ":G" + (c?.row ?? 2),
    now,
  };
}

