export default function check({ body, statusCode }) {
  if (
    statusCode < 200 ||
    statusCode >= 300 ||
    !body ||
    !Array.isArray(body.messages) ||
    !body.messages.length
  )
    throw Error("Cannot verify Gmail conversation");
  return {
    unanswered: body.messages.every(
      (m) =>
        (Array.isArray(m.labelIds) && m.labelIds.includes("SENT")) ||
        (Array.isArray(m.labels) && m.labels.some((x) => x.id === "SENT")),
    ),
  };
}

